public class Main {
    public static void main(String[] args) {
        Car car = new Car("Toyota", 2020);
        car.describe();
        car.drive(150);
        car.drive(30);
        System.out.println("Odometer: " + car.getKm());
    }
}

class Car {
    private String model;
    private int year;
    private int km;

    Car(String model, int year) {
        this.model = model;
        this.year = year;
    }

    void drive(int distance) {
        km += distance;
    }

    int getKm() {
        return km;
    }

    void describe() {
        System.out.println(year + " " + model);
    }
}
